# --- 分割で作る Issue ----------------------------------------------------------

def split_from_line(declaration_url):
    """分割で作る Issue の本文の先頭行。declaration_url は分割の元の宣言のコメントの URL
    (`https://github.com/owner/repo/issues/番号#issuecomment-<id>`)。その形でなければ None。"""
    if not isinstance(declaration_url, str) or not _DECLARATION_URL_RE.match(declaration_url.strip()):
        return None
    return SPLIT_FROM_PREFIX + declaration_url.strip()


def _first_line(body):
    return (body or "").split("\n", 1)[0].strip()


def create_issue(repo, title, body, declaration_url, labels=(), assignees=()):
    """分割で Issue を作る。本文の先頭行に分割の元 (宣言のコメントの URL) を書き、同じ先頭行を持つ開いた Issue が
    既にあれば作らずにその番号を返す (再開のときに 2 つ作らない。AE44)。Status と sub-issue の関係は書かない。

    返り値: {"status": "ok", "created": bool, "number", "url"} か失敗の説明。開いた Issue の一覧が読めなければ作らない
    (既にあるかを確認できないまま作ると 2 つになりうるため)。
    """
    first = split_from_line(declaration_url)
    if first is None:
        return {"status": "error", "failure": "other", "exit_code": None,
                "message": f"分割の元は宣言のコメントの URL (https://github.com/owner/repo/issues/番号#issuecomment-<id>) で指す: {declaration_url!r}"}
    if not isinstance(repo, str) or not re.fullmatch(ids.REPO_NAME_PATTERN, repo):
        return {"status": "error", "failure": "other", "exit_code": None, "message": f"リポジトリは owner/name の形: {repo!r}"}
    r = gh.run(["issue", "list", "-R", repo, "--state", "open", "--json", "number,url,body", "--limit", str(LIST_LIMIT)], expect_json=True)
    if r["failure"] or not isinstance(r["json"], list):
        return _error(r)
    for issue in r["json"]:
        if _first_line(issue.get("body")) == first:
            return {"status": "ok", "created": False, "number": issue["number"], "url": issue["url"]}
    args = ["issue", "create", "-R", repo, "--title", title, "--body", f"{first}\n\n{body}"]
    for label in labels:
        args += ["--label", label]
    for assignee in assignees:
        args += ["--assignee", assignee]
    r = gh.run(args, mutation=True)
    created = ids.parse_issue_ref(r["stdout"].strip().split("\n")[-1] if r["stdout"].strip() else "")
    if r["failure"] or r["exit_code"] != 0 or created is None:
        return _error(r)
    return {"status": "ok", "created": True, "number": created["number"], "url": created["url"]}


# --- blockedBy -----------------------------------------------------------------

def add_blocked_by(issue, blocker):
    """issue の `blockedBy` に blocker を足す (`gh issue edit <URL> --add-blocked-by <URL>`。URL の形だけを受け付ける。U1)。
    返り値: {"status": "ok", "issue", "blocker"} (キーは `owner/repo#番号`) か失敗の説明。失敗しても再試行しない。"""
    issue_ref, blocker_ref = ids.parse_issue_ref(issue), ids.parse_issue_ref(blocker)
    if issue_ref is None or blocker_ref is None:
        return {"status": "error", "failure": "other", "exit_code": None,
                "message": f"Issue の参照 (owner/repo#番号 か URL) ではない: {issue!r} / {blocker!r}"}
    r = gh.run(["issue", "edit", issue_ref["url"], "--add-blocked-by", blocker_ref["url"]], mutation=True)
    if r["failure"] or r["exit_code"] != 0:
        return _error(r)
    return {"status": "ok", "issue": issue_ref["key"], "blocker": blocker_ref["key"]}


#!/usr/bin/env python3
"""テストで、PATH の先頭に gh の名前で置く偽のコマンド。

実際の gh の代わりに、環境変数の指示どおりに振る舞う (先例: review-triage/tests/fake-claude)。

- FAKE_GH_ARGS: 受けた引数 (argv[1:]) と標準入力の中身 (stdin) と時刻と cwd を JSON の 1 行として追記するファイル
- FAKE_GH_SLEEP: 応答の前に待機する秒数 (既定 0)
- FAKE_GH_FIXTURES: 固定データのディレクトリ (既定はこのファイルと同じディレクトリの fixtures/gh)
- FAKE_GH_MODE:
    ok              FAKE_GH_RESPONSES の応答の指定に従う (既定)
    auth_expired    固定データ auth-invalid-token を返す (終了コード 1)
    not_logged_in   固定データ auth-not-logged-in を返す (終了コード 4)
    rate_limited    固定データ graphql-rate-limited を返す (終了コード 1)
    network         固定データ network-unreachable を返す (終了コード 1)
    hang            応答せずに終了しない (呼び出し元のタイムアウトを試す)
    exit            何も書かずに FAKE_GH_EXIT (既定 1) で終了する
- FAKE_GH_RESPONSES: 応答の指定の JSON ファイル。要素の配列で、受けた引数に最初に一致した要素を返す。要素のキー:
    prefix    引数の先頭がこの配列と同じなら一致 (例: ["issue", "view"])
    contains  この配列の要素をすべて含めば一致 (prefix と両方書けば両方)
    substring この文字列を含む引数が 1 つでもあるか、標準入力の中身に含まれれば一致 (GraphQL の操作名 "query ProjectItems" などで
              識別する。`gh api graphql --input -` の本文は標準入力に来る)。文字列の配列なら、すべてが一致すること。ほかの条件と両方書けば両方
    stdout    標準出力に書く文字列。オブジェクトや配列なら JSON にして書く。{"fixture": "<場合>"} なら固定データの <場合>.stdout の中身
    stderr    標準エラー出力に書く文字列 (既定は空)
    exit      終了コード (既定 0)
    once      真なら 1 回だけ使い、使ったら used を真にしてファイルに書き戻す (書き込みの直後に別の値を返す場合を表す)
  一致する要素が無ければ、標準エラー出力に引数を書いて終了コード 99 で終了する (指定の漏れを、成功した応答と取り違えないため)
"""

import json
import os
import sys
import time

HERE = os.path.dirname(os.path.realpath(__file__))  # シンボリックリンクで gh の名前に置かれるので、実体の場所


def fixture(name, kind):
    base = os.environ.get("FAKE_GH_FIXTURES") or os.path.join(HERE, "fixtures", "gh")
    try:
        with open(os.path.join(base, f"{name}.{kind}"), encoding="utf-8") as f:
            return f.read()
    except OSError:
        return ""


def record(args, stdin_text):
    path = os.environ.get("FAKE_GH_ARGS")
    if path:
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps({"args": args, "stdin": stdin_text, "time": time.time(), "cwd": os.getcwd()}, ensure_ascii=False) + "\n")


def respond(stdout, stderr, exit_code):
    sys.stdout.write(stdout)
    sys.stdout.flush()
    sys.stderr.write(stderr)
    sys.stderr.flush()
    sys.exit(exit_code)


def matches(entry, args, stdin_text):
    prefix = entry.get("prefix")
    contains = entry.get("contains")
    substring = entry.get("substring")
    if prefix is not None and args[:len(prefix)] != list(prefix):
        return False
    if contains is not None and not all(c in args for c in contains):
        return False
    if substring is not None:
        needles = [substring] if isinstance(substring, str) else list(substring)
        if not all(any(s in a for a in args) or s in stdin_text for s in needles):
            return False
    return prefix is not None or contains is not None or substring is not None


def main():
    args = sys.argv[1:]
    stdin_text = "" if sys.stdin.isatty() else sys.stdin.read()
    record(args, stdin_text)
    sleep = float(os.environ.get("FAKE_GH_SLEEP", "0") or 0)
